ween;align-items:center;gap:15px;margin-bottom:18px}.tts-demo .dialog-head button{border:0;font-size:18px;padding:0 7px}.tts-demo .dialog-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.tts-demo .empty{padding:40px 12px;text-align:center;color:var(--muted)}.tts-demo .danger{color:#b34747}.tts-demo .plan-link{margin-top:14px;font-size:12px;text-align:right}
